return'／形：'+(SHAPE_LABEL[info.p]||info.p)+hubNote+'／嫉妬：'+JEAL_LABEL[info.jeal]+(info.j?'（'+info.j+'）':'')+'／受けの開放度：'+OPEN_LABEL[info.open]+(info.s?'（'+info.s+'）':'')+(info.after?'／結末：'+{sour:'険悪',bond:'連帯',yield:'折れた'}[info.after]:'');
