var OWNER={ceo:1,hotelier:1,shopowner:1};
function biz(c){return c.om.job==='ceo'?'会社':c.om.job==='hotelier'?(c.om.hotel?'「'+c.om.hotel+'」':'ホテル'):c.om.shop||'店';}
var IV={
pitch:L('{o}は{i}に、{biz}の事業計画を一時間かけて説明した。{i}は最後まで表情を変えず、最後に一つだけ質問した。「あなたは、これに人生を賭けられる？｜あなたは、これに人生を賭けられるか｜あなたは、これに人生を賭けられますか」|{i}は{o}の{biz}を、客のふりをして三回訪れてから、出資の話を切り出した。'),
deal:L('{i}は{o}の{biz}に出資を決めた。契約書に判を押したあと、{i}は「数字じゃなく、あなたに賭けた｜数字ではなく、あなたに賭けた｜数字ではなく、あなたに賭けました」と言った。|{o}は{i}から出資を受けた。条件はひとつ、「毎月、直接会って報告すること」だった。'),
tough:L('{i}は{o}に、出資の条件として赤字部門の切り捨てを迫った。{o}は従業員の顔を思い浮かべて、首を縦に振らなかった。|経営会議で、{i}は{o}の方針に真っ向から反対した。二人とも、一歩も引かなかった。'),
save:L('{o}の{biz}が資金繰りに行き詰まったとき、{i}は誰にも言わずに追加の出資をした。|{i}は{o}の{biz}を狙う買収話を、自分の持ち株で止めた。「あなたの店を、他の誰かに渡す気はない｜＝｜あなたの店を、他の誰かに渡す気はありません」'),
buyout:L('{i}は{o}の{biz}の株を、少しずつ買い集めていた。{o}がそれに気づいたのは、筆頭株主の欄に{i}の名前を見つけたときだった。|{i}は{o}に買収を持ちかけた。「経営は続けていい。ただ、あなたごと買いたい｜＝｜経営は続けてかまいません。ただ、あなたごと買いたいんです」'),
romance:L('出資の報告会のあと、{i}は{o}を食事に誘った。「今夜は、投資家としてじゃない｜今夜は、投資家としてではない｜今夜は、投資家としてではありません」|{o}は{i}との契約書の最後のページに、手書きの一行を見つけた。「個人的な好意は、この契約とは関係ない｜＝｜個人的な好意は、この契約とは関係ありません」'),
heatO:L('{o}は{i}との大事な商談の最中に発情期を迎えかけた。{i}は何も言わずに商談を打ち切り、自分のハイヤーで{o}を家まで送らせた。|{i}は{o}の発情期の周期を知っていて、その週の会議を全部オンラインに切り替えていた。'),
tension:L('{o}は「あなたのお金で経営しているわけじゃない｜あなたの金で経営しているわけではない｜あなたのお金で経営しているわけではありません」と言い放った。{i}は笑って、「知ってる。だから出資した｜知っている。だから出資した｜知っています。だから出資しました」と返した。|{i}が{o}の{biz}の内装にまで口を出し、{o}は初めて声を荒らげた。')
};
OM.EXTRA_EV=OM.EXTRA_EV||[];
OM.EXTRA_EV.push({
id:'om_investor',cat:'bond',scope:'pair',
when:function(ctx,a,b){
if(a.om.former||b.om.former)return false;
return(a.om.job==='investor'&&OWNER[b.om.job])||(b.om.job==='investor'&&OWNER[a.om.job]);
},
w:function(ctx,a){return 1.1+(a.action.id==='work'?0.4:0);},
run:function(ctx,a,b){
var I=a.om.job==='investor'?a:b,O=I===a?b:a,pf=ctx.pair(I,O),st=(pf.iv=pf.iv||{}),rIO=ctx.R(I,O),rOI=ctx.R(O,I),rng=ctx.rng;
var k,cat='bond',why='投資家（'+I.name+'）と経営者（'+O.name+'・'+OM.jobName(O)+'）';
if(!st.met){k='pitch';st.met=true;ctx.mod2(I,O,{trust:3},{ten:3});why+='：出資の打診';}
else if(!st.deal&&(rIO.trust>20||I.tr.a>0.55)){k='deal';st.deal=true;cat='help';ctx.mod2(I,O,{trust:5},{trust:8,aff:3});why+='：出資が決まった';}
else if(O.om.sex==='o'&&O.om.heat>0&&st.deal){k='heatO';cat='help';ctx.mod2(I,O,{att:4},{trust:10,aff:6});why+='：商談中の発情期への配慮';}
else if(st.deal&&rIO.att>32&&rOI.att>25&&rng()<0.5){k='romance';cat='romance';ctx.mod2(I,O,{att:6},{att:6});why+='：仕事の関係から一歩踏み出す';}
else if(st.deal&&rIO.aff>30&&rng()<0.35){k='save';cat='help';ctx.mod2(I,O,{aff:4},{trust:12,aff:8});why+='：'+I.name+'の肩入れ（好意 '+Math.round(rIO.aff)+'）';}
else if(I.tr.cp+I.tr.cold>1.1&&rng()<0.45){k=rng()<0.4?'buyout':'tough';cat='conflict';ctx.mod2(I,O,{ten:3},{ten:10,trust: -3});why+='：'+I.name+'の冷徹さ（CP・冷たさ）';}
else{k='tension';cat='conflict';ctx.mod2(I,O,{ten:3,att:2},{ten:6,att:2});why+='：経営をめぐる言い合い';}
var t=ctx.pick(IV[k]).replace(/\{i\}/g,I.name).replace(/\{o\}/g,O.name).replace(/\{biz\}/g,biz(O));
return{cat:cat,text:t,why:why,mag:k==='deal'||k==='save'||k==='buyout'||k==='romance'?18:8};
}
});
function nonWorker(c){return!!c&& !!c.om&&(c.om.job==='neet'||c.om.job==='student'||c.om.former||c.om.quit);}
function kindOf(c){return c.om.job==='student'&& !c.om.former&& !c.om.quit?'student':'none';}
