Z.cureAssault=function(ctx,a,b,mates,lv,opt){
opt=opt||{};
var m={a:a.name,b:b.name,m:mates&&mates.length?mates.map(function(x){return x.name;}).slice(0,2).join('・'):''};
var C=Z.Cover,ero=lv==='high'&&C&&C.ero(ctx,a);
if(opt.second&&ero)return C.efill(ctx,C.pick(ctx,CE.second),a,{v:a.name,a:a.name,b:b.name},true);
if(opt.second)return fill(ctx.pick(SECOND),{a:opt.first.name,m:a.name});
if(lv!=='high')return fill(ctx.pick(FADE),m);
if(ero){
var k=C.kind(a),sh=HK.Lewd.short(ctx.env,ctx.rng),m2={v:a.name,a:a.name,b:b.name,m:m.m};
var te=C.efill(ctx,C.pick(ctx,CE.act[k]),a,m2)+fill(ctx.pick(AS[a.persona]||AS.gentle),m);
if(!sh){
if(m.m&&ctx.rng()<0.7)te+=fill(ctx.pick(SEEN),m);
if(ctx.rng()<0.4)te+=fill(ctx.pick(MEM),m);
}
te+=C.peak(ctx,a,'触手',m2);
if(!sh)te+=C.efill(ctx,C.pick(ctx,CE.fin),a,m2,true);
if(!sh&&HK.Lewd.high(ctx.env))te+=C.efill(ctx,C.pick(ctx,CE.again),a,m2,true);
return te;
}
var t=fill(ctx.pick(HIGH_OPEN),m)+fill(ctx.pick(AS[a.persona]||AS.gentle),m);
if(m.m&&ctx.rng()<0.7)t+=fill(ctx.pick(SEEN),m);
if(ctx.rng()<0.55)t+=fill(ctx.pick(MEM),m);
t+=fill(ctx.pick(FILL),m);
return t;
};
