var lead=(l0?l0+'\n\n':'')+MK('S')+'\n\n';
var extra=[(mids.length&&ctx.rng()<0.7?xy(pk(mids)):'')+MK('M')];
var finish=pk(kd==='ff'?FIN.filter(function(l){return!/繋が/.test(l);}):FIN)+MK('A');
var t=TK.body(T,U,{flav:'zombie',pick:pk,rng:ctx.rng,bed:'毛布',depth:ctx.rng()<0.4?3:2,lead:lead,extra:extra,finish:finish,noAfter:true});
t=fillTop(ctx,TK.names(t,T,U),T,U,3,pre).replace(/^\n+|\n+$/g,'');
