var CV=Z.Cover={};
CV.inv=function(c){var S=HK.State,P=HK.Pos;return!!c&& !HK.SAFE_ON&& !c.noR18&&(!S||S.mobSexOk(c))&&(!P||P.canReceive(c))&& !(c.sexLocks&&c.sexLocks.length)&& !(P&&P.noGen&&P.noGen(c));};
CV.hot=function(c){var S=HK.State,P=HK.Pos;return!!c&& !HK.SAFE_ON&& !c.noR18&&(!S||S.r18ok(c))&&(!P||P.hasM(c)||P.hasF(c));};
CV.room=function(ctx){return(ctx._shieldN||0)<2;};
CV.use=function(ctx){ctx._shieldN=(ctx._shieldN||0)+1;};
CV.pick=function(ctx,arr){return HK.Ero&&HK.Ero.fresh?HK.Ero.fresh(ctx,arr,function(l){return ctx.pick(l);}):ctx.pick(arr);};
CV.ero=function(ctx,x){return!!(HK.Ero&&HK.Lewd&&HK.Lewd.ero(ctx.env)&&Z.loveLv(ctx)==='high'&& !(HK.Pos&&HK.Pos.noGen&&HK.Pos.noGen(x)));};
CV.kind=function(x){return HK.Pos&& !HK.Pos.hasF(x)?'m':'f';};
CV.rel=function(ctx,h,v){
var T=HK.Ties,has=function(k){return!!(T&&T.has&&(T.has(ctx,h,v,k)||T.has(ctx,v,h,k)));};
if((Z.isLover&&Z.isLover(ctx,h,v))||has('spouse')||has('fiance'))return'lover';
if(has('fwb')||(h.sexLocks||[]).indexOf(v.i)>=0||(v.sexLocks||[]).indexOf(h.i)>=0)return'fixed';
if(Z.isCrush&&Z.isCrush(ctx,h,v))return'crush';
if(hate(ctx,h,v)||hate(ctx,v,h))return'enemy';
if(has('apathy')||ctx.R(h,v).aff<8)return'cold';
return'friend';
};
var VK=['start','mid','climax'];
CV.moan=function(ctx,x,kind,late){
var strong= !!(HK.R18M&&HK.R18M.isStrong&&HK.R18M.isStrong(x));
if(HK.Moan&&HK.Moan.say)return HK.Moan.say(ctx,x,kind,{force:true,hush:strong,late: !!late});
return HK.Ero.moan(ctx,x,{start:0,mid:1,climax:2}[kind]||0,{force:true});
};
CV.mob=function(ctx,st){return HK.Ero.moan(ctx,{mob:true,mobRole:'guest',mobTop:true,gender:'m',name:'男'},st);};
CV.efill=function(ctx,t,x,mp,late,h){
return fill(String(t),mp).replace(/\{s:(\w+)\}/g,function(s,k){return HK.Ero.sfx(ctx,k);})
.replace(/\{v([012])\}/g,function(s,n){return CV.moan(ctx,x,VK[+n],late||n==='2');})
.replace(/\{h([012])\}/g,function(s,n){return h?CV.moan(ctx,h,VK[+n],late||n==='2'):'……っ';})
.replace(/\{mm\}/g,function(){return'「'+CV.mob(ctx,2)+'」';});
};
