CV.peak=function(ctx,x,foe,mp){
var ps=(HK.personaOf?HK.personaOf(x):x.persona)||'gentle',m2={};
Object.keys(mp||{}).forEach(function(k){m2[k]=mp[k];});
m2.v=x.name;m2.x=foe;
return CV.efill(ctx,CV.pick(ctx,PEAK[ps]||PEAK.gentle),x,m2,true)+x.name+'「'+CV.moan(ctx,x,'climax',true)+'」';
};
function raidEro(ctx,x,mx){
var k=CV.kind(x),sh=HK.Lewd.short(ctx.env,ctx.rng),m2={};
Object.keys(mx).forEach(function(q){m2[q]=mx[q];});
m2.v=x.name;
var t=CV.efill(ctx,CV.pick(ctx,RE.act[k]),x,m2);
if(!sh)t+=CV.efill(ctx,CV.pick(ctx,RE.mid),x,m2)+(m2.m&&ctx.rng()<0.6?fill(ctx.pick(RT.seen),m2):'');
t+=CV.peak(ctx,x,'男たち',m2);
if(!sh)t+=CV.efill(ctx,CV.pick(ctx,RE.fin[k]),x,m2,true);
if(!sh&&HK.Lewd.high(ctx.env))t+=CV.efill(ctx,CV.pick(ctx,RE.again),x,m2,true);
return t;
}
