var calm=ctx.most(P,function(c){return c.tr.a-c.tr.ac*0.3;});
if(calm&&calm.tr.a>0.65)ctx.act2({actors:[calm],cat:'escape',text:ctx.t('{a}は暗闇のあいだ、壁に耳を当てて、外の物音を聞いていた。',calm),why:calm.name+'のA'});
